import { tokenStore, TokenRecord } from "./tokenStore";
import { loadTokenConfig } from "./config";
import { randomId, nowSeconds } from "./utils";

export interface TokenPair {
  accessToken: string;
  refreshToken: string;
  expiresAt: number;
}

export class AuthError extends Error {
  constructor(public code: string) {
    super(code);
  }
}

export function issueTokenPair(userId: string): TokenPair {
  const cfg = loadTokenConfig();
  return {
    accessToken: `at_${userId}_${randomId()}`,
    refreshToken: `rt_${userId}_${randomId()}`,
    expiresAt: nowSeconds() + cfg.ttlSeconds,
  };
}

// Lưu trữ promise của các request refresh đang chạy cho mỗi refreshToken hoặc active pair map
const refreshInFlight = new Map<string, Promise<TokenPair>>();
// Lưu trữ ánh xạ từ refresh token cũ sang token pair mới đã được cấp trong khoảng thời gian ngắn (grace period / deduplication)
const recentRefreshes = new Map<string, TokenPair>();

/**
 * Đổi refresh token lấy cặp token mới. Refresh token cũ bị thu hồi (rotation).
 * Được gọi từ session.ts khi access token hết hạn; client có thể gọi song song.
 */
export async function refresh(refreshToken: string): Promise<TokenPair> {
  // 1. Kiểm tra nếu có request refresh đồng thời cho chính refreshToken này
  const existingPromise = refreshInFlight.get(refreshToken);
  if (existingPromise) {
    return existingPromise;
  }

  // 2. Kiểm tra nếu refreshToken này vừa mới được refresh thành công gần đây (để xử lý các request đồng thời hoặc retry sát nhau)
  const recent = recentRefreshes.get(refreshToken);
  if (recent) {
    return recent;
  }

  const promise = (async (): Promise<TokenPair> => {
    const record: TokenRecord | undefined = await tokenStore.get(refreshToken);
    if (!record || record.revoked) {
      throw new AuthError("ERR_TOKEN_REUSED");
    }
    // rotate: thu hồi token cũ rồi phát hành cặp mới
    await tokenStore.revoke(refreshToken);
    const pair = issueTokenPair(record.userId);
    await tokenStore.save(pair.refreshToken, { userId: record.userId, revoked: false });

    // Lưu vào recentRefreshes và tự động xóa sau 5 giây để tránh memory leak
    recentRefreshes.set(refreshToken, pair);
    setTimeout(() => {
      if (recentRefreshes.get(refreshToken) === pair) {
        recentRefreshes.delete(refreshToken);
      }
    }, 5000);

    return pair;
  })();

  refreshInFlight.set(refreshToken, promise);
  try {
    return await promise;
  } finally {
    refreshInFlight.delete(refreshToken);
  }
}

